// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint256 nftSeed, uint256 baseSeed, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bool useOracle, bool payRoyalties) public {
        vm.assume(feeRate <= 5000);
        // Deploy adversarial NFT contract that calls back into initialize during its safeTransferFrom
        ReentrantNft nftToken = new ReentrantNft(address(c), baseSeed, vBase, vNft, changeFee, feeRate, useOracle, payRoyalties);
        // baseToken is address(this) (a non-reverting EOA)
        try c.initialize(address(this), address(nftToken), vBase, vNft, changeFee, feeRate, bytes32(0), useOracle, payRoyalties) {
            // After initialize, baseToken must equal the passed _baseToken argument
            assertTrue(c.baseToken() == address(this));
        } catch {
            // If initialize reverts, the mutation doesn't manifest; pass vacuously
            assertTrue(true);
        }
    }
}

contract ReentrantNft {
    C target;
    uint256 baseSeed;
    uint128 vBase;
    uint128 vNft;
    uint56 changeFee;
    uint16 feeRate;
    bool useOracle;
    bool payRoyalties;
    constructor(address _target, uint256 _baseSeed, uint128 _vBase, uint128 _vNft, uint56 _changeFee, uint16 _feeRate, bool _useOracle, bool _payRoyalties) {
        target = C(payable(_target));
        baseSeed = _baseSeed;
        vBase = _vBase;
        vNft = _vNft;
        changeFee = _changeFee;
        feeRate = _feeRate;
        useOracle = _useOracle;
        payRoyalties = _payRoyalties;
    }
    // Adversarial safeTransferFrom that re-enters initialize with a different _baseToken
    function safeTransferFrom(address, address to, uint256) external {
        if (to == address(target)) {
            // Re-enter initialize, this time with a different baseToken (address(this))
            target.initialize(address(this), address(this), vBase, vNft, changeFee, feeRate, bytes32(0), useOracle, payRoyalties);
        }
    }
}
